ankuendigung_vorlaufvergleich <- function(vorlauffall=NULL, zugang_am=NULL, beabsichtigter_beginn_am=NULL, einordnungsnachweis=NULL) {
 .auswahl(vorlauffall,'vorlauffall',c('modernisierung_555c','waermeumstellung_556c','mietaufrechnung_556b','zahlungsdienste_aenderung_675g','urlaubsprodukt_zahlung_486a','gastschul_information_651u','zahlung_vorabinformation_675x'))
 .datum(zugang_am,'zugang_am');beginn <- .datum(beabsichtigter_beginn_am,'beabsichtigter_beginn_am');.text(einordnungsnachweis,'einordnungsnachweis')
 faelle <- list(modernisierung_555c=list(3,'monate'),waermeumstellung_556c=list(3,'monate'),mietaufrechnung_556b=list(1,'monate'),zahlungsdienste_aenderung_675g=list(2,'monate'),urlaubsprodukt_zahlung_486a=list(2,'wochen'),gastschul_information_651u=list(2,'wochen'),zahlung_vorabinformation_675x=list(4,'wochen'))
 f <- faelle[[vorlauffall]];ablauf <- .frist(zugang_am,f[[1]],f[[2]],'ereignis');frueh <- .tage_addieren(ablauf,1)
 wert <- list(vorlauf_ablauf_am=.iso(ablauf),fruehester_beginn_am=.iso(frueh),vorlauf_eingehalten=beginn>=frueh)
 eingaben <- list(vorlauffall=vorlauffall, zugang_am=zugang_am, beabsichtigter_beginn_am=beabsichtigter_beginn_am, einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,"daten_und_wahrheitswert","BGB_ANKUENDIGUNG_VORLAUFVERGLEICH",eingaben,list(list(operation="Gesetzlichen Mindestvorlauf ab Zugang berechnen und Beginn nach vollst\u00e4ndigem Fristablauf vergleichen.")),eingaben)
 ergebnis$hinweise <- list("Mindestvorlauf ab tats\u00e4chlichem Zugang nach \u00a7\u00a7187I/188 vorw\u00e4rts berechnen; der Zieltagesbeginn muss nach dem Ablaufdatum liegen. Nur kalendert\u00e4glicher Vorlauf, keine eigenst\u00e4ndige qualitative Wirksamkeitsentscheidung und keine automatische Fristverschiebung nach\u00a7193. Bei versp\u00e4teter Ank\u00fcndigung wird der tats\u00e4chlich beabsichtigte Beginn nicht automatisch ge\u00e4ndert. \u00a7555cIV Bagatellausnahme, \u00a7556cI sonstige Umstellungsvoraussetzungen, \u00a7556bII zul\u00e4ssiger Forderungstyp und Textform, \u00a7675gII Zustimmung/Abs\u00e4tze3und4-Ausnahmen, \u00a7486a Zahlungsplan und \u00a7651uIII vollst\u00e4ndige Information/angemessene Vorbereitung gesondert. \u00a7675xIII betrifft nur den Vierwochenvorlauf; direkte Zustimmung, wirksame Ausschlussvereinbarung und erforderliche Information sind gesonderte Voraussetzungen, kein automatischer Erstattungsausschluss. Untert\u00e4gige Zeitpunktvereinbarungen sind nicht durch ein blo\u00dfes Datum abgebildet. Keine pauschale30-Tage-Monatsrechnung.")
 ergebnis
}
